SELECT CASE WHEN octet_length(o.object_id)=32 THEN o.object_id END,o.role::bigint,o.canonical_length::bigint,o.group_number::bigint,o.record_number::bigint,p.pack_id,p.domain,CASE WHEN octet_length(p.digest)=32 THEN p.digest END,p.length FROM unnest($1::bytea[],$2::bigint[]) k(i,k) CROSS JOIN LATERAL (SELECT * FROM {schema}.object_location x WHERE ('x'||encode(substring(x.object_id FROM 1 FOR 8),'hex'))::bit(64)::bigint=k.k AND x.object_id=k.i OFFSET 0) o JOIN {schema}.pack p ON p.pack_id=o.pack_id
